"""NIST ACVP ML-KEM-1024 keyGen / encaps / decaps vectors, parsed from the
vendored C header.

``hw/sys/sep/dv/fw/tests/common/abr_nist_kem_vectors.h`` is generated by
``fw/tests/common/gen_abr_nist_vectors.py --mlkem`` from the NIST ACVP-Server
internalProjection. This module is the Python golden for the no_cpu ML-KEM KAT;
it does not re-encode the words.

The decaps pair is the load-bearing part. FIPS-203 uses implicit rejection: a
modified ciphertext does not raise an error, it yields a DIFFERENT shared key.
So the rejecting case carries its own expected K and is graded by value. Each
ACVP decaps case has its own decapsulation key, so the two are not one key
walked twice and neither can be derived from the other.

Same limit as ``sep_abr_nist``: these are transcribed authority values, not a
recomputable construction, so the import-time assertions are shape and
non-degeneracy only. They would not catch a transcription error that preserved
length. The defence is that the header is generated, never hand-edited.
"""

from __future__ import annotations

import re
from pathlib import Path

_HEADER = Path(__file__).resolve().parents[2] / "fw" / "tests" / "common" / "abr_nist_kem_vectors.h"


def _load_u32_array(name: str) -> list[int]:
    text = _HEADER.read_text(encoding="utf-8")
    m = re.search(
        rf"static const uint32_t {name}\[(\d+)\] = \{{(.*?)\}};",
        text,
        re.S,
    )
    if not m:
        raise RuntimeError(f"{name} not found in {_HEADER}")
    words = [int(tok, 16) for tok in re.findall(r"0x([0-9a-fA-F]+)u", m.group(2))]
    n = int(m.group(1))
    if len(words) != n:
        raise RuntimeError(f"{name}: parsed {len(words)} words, header says {n}")
    return words


# keyGen: the two seeds in, the two keys out.
NIST_KEM_KG_D = _load_u32_array("nist_kem_kg_d")
NIST_KEM_KG_Z = _load_u32_array("nist_kem_kg_z")
NIST_KEM_KG_EK = _load_u32_array("nist_kem_kg_ek")
NIST_KEM_KG_DK = _load_u32_array("nist_kem_kg_dk")

# encaps: ek + the message randomness m fix the ciphertext and the shared key.
NIST_KEM_ENC_EK = _load_u32_array("nist_kem_enc_ek")
NIST_KEM_ENC_M = _load_u32_array("nist_kem_enc_m")
NIST_KEM_ENC_C = _load_u32_array("nist_kem_enc_c")
NIST_KEM_ENC_K = _load_u32_array("nist_kem_enc_k")

# decaps: one ACVP "valid decapsulation" case and one "modified ciphertext".
NIST_KEM_DEC_OK_DK = _load_u32_array("nist_kem_dec_ok_dk")
NIST_KEM_DEC_OK_C = _load_u32_array("nist_kem_dec_ok_c")
NIST_KEM_DEC_OK_K = _load_u32_array("nist_kem_dec_ok_k")

NIST_KEM_DEC_BAD_DK = _load_u32_array("nist_kem_dec_bad_dk")
NIST_KEM_DEC_BAD_C = _load_u32_array("nist_kem_dec_bad_c")
NIST_KEM_DEC_BAD_K = _load_u32_array("nist_kem_dec_bad_k")

# Shapes. ML-KEM-1024: ek 1568 B, dk 3168 B, ct 1568 B, K and each seed 32 B.
_EK_WORDS = 392
_DK_WORDS = 792
_CT_WORDS = 392
_K_WORDS = 8
_SEED_WORDS = 8

for _name, _v, _n in (
    ("NIST_KEM_KG_D", NIST_KEM_KG_D, _SEED_WORDS),
    ("NIST_KEM_KG_Z", NIST_KEM_KG_Z, _SEED_WORDS),
    ("NIST_KEM_ENC_M", NIST_KEM_ENC_M, _SEED_WORDS),
    ("NIST_KEM_KG_EK", NIST_KEM_KG_EK, _EK_WORDS),
    ("NIST_KEM_ENC_EK", NIST_KEM_ENC_EK, _EK_WORDS),
    ("NIST_KEM_KG_DK", NIST_KEM_KG_DK, _DK_WORDS),
    ("NIST_KEM_DEC_OK_DK", NIST_KEM_DEC_OK_DK, _DK_WORDS),
    ("NIST_KEM_DEC_BAD_DK", NIST_KEM_DEC_BAD_DK, _DK_WORDS),
    ("NIST_KEM_ENC_C", NIST_KEM_ENC_C, _CT_WORDS),
    ("NIST_KEM_DEC_OK_C", NIST_KEM_DEC_OK_C, _CT_WORDS),
    ("NIST_KEM_DEC_BAD_C", NIST_KEM_DEC_BAD_C, _CT_WORDS),
    ("NIST_KEM_ENC_K", NIST_KEM_ENC_K, _K_WORDS),
    ("NIST_KEM_DEC_OK_K", NIST_KEM_DEC_OK_K, _K_WORDS),
    ("NIST_KEM_DEC_BAD_K", NIST_KEM_DEC_BAD_K, _K_WORDS),
):
    assert len(_v) == _n, f"{_name}: {len(_v)} words, expected {_n}"

# Non-degeneracy: an all-zero expected value would pass against a window that
# reads back zero, which is exactly what an unstarted engine returns.
for _name, _v in (
    ("NIST_KEM_KG_EK", NIST_KEM_KG_EK),
    ("NIST_KEM_KG_DK", NIST_KEM_KG_DK),
    ("NIST_KEM_ENC_C", NIST_KEM_ENC_C),
    ("NIST_KEM_ENC_K", NIST_KEM_ENC_K),
    ("NIST_KEM_DEC_OK_K", NIST_KEM_DEC_OK_K),
    ("NIST_KEM_DEC_BAD_K", NIST_KEM_DEC_BAD_K),
):
    assert any(w != 0 for w in _v), f"{_name} is all zero"

# The implicit-rejection case must differ from the accepting one on both the
# input and the expected output, or the reject leg could not fail.
assert NIST_KEM_DEC_OK_C != NIST_KEM_DEC_BAD_C, "the two decaps ciphertexts are identical"
assert NIST_KEM_DEC_OK_K != NIST_KEM_DEC_BAD_K, (
    "the valid and modified-ciphertext decaps cases expect the same shared key, "
    "so implicit rejection would not be observable"
)
